from hran_elementmanager2g.utils.loggers import logger
import socket
import sys
from time import sleep
import os
import platform

if platform.python_implementation() == 'CPython':
    import paramiko



class SshClient(object):
    """ tbc """

    def __init__(self, host, ssh_user, ssh_password, connect=True):
        self.host = host
        self.ssh_user = ssh_user
        self.ssh_password = ssh_password
        self.ssh_client = paramiko.SSHClient()
        self.ssh_client.set_missing_host_key_policy(paramiko.AutoAddPolicy())
        if connect:
            logger.debug('ssh login:' + str(host) + " " + str(ssh_user) + " " + str(ssh_password))
            self.ssh_client.connect(hostname=host, username=ssh_user, password=ssh_password)
        self.outputSshCommandList = []
        self.outputSshCommand = ''
        self.AprThread = None

    def __del__(self):
        """ tbc """
        self.ssh_close_connection()

    def is_connected(self):
        """ tbc """
        if self.ssh_client:
            logger.debug("self.SshCilent exists")
            TR = self.ssh_client.get_transport()
            if TR:
                if TR.is_active():
                    logger.debug("transport is_active")
                    return TR.is_active()
                else:
                    logger.debug("transport is_dead")
                    return TR.is_active()
            else:
                logger.debug("transport is_dead")
                return False
        else:
            return False

    def ssh_send_command(self, command, timeout2=10):
        """ tbc """
        logger.debug("fun_call: " + sys._getframe().f_code.co_name)
        logger.debug(command)
        self.stdin, self.stdout, self.stderr = self.ssh_client.exec_command(command, timeout=timeout2)
        try:
            for line in iter(self.stdout.readline, ''):
                self.outputSshCommandList.append(line)
                logger.debug(line)
        except socket.timeout:
            logger.debug('socket timeout in stdout')
        try:
            for line in iter(self.stderr.readline, ''):
                self.outputSshCommandList.append(line)
                logger.debug(line)
        except socket.timeout:
            logger.debug('socket timeout in stderr')

    def ssh_send_cmd_and_return_output(self, command, timeout2=10):
        """ tbc """
        logger.debug("fun_call: " + sys._getframe().f_code.co_name)
        logger.debug(command)
        output = []
        self.stdin, self.stdout, self.stderr = self.ssh_client.exec_command(command, timeout=timeout2)
        try:
            for line in iter(self.stdout.readline, ''):
                output.append(line)
                logger.debug(line)
        except socket.timeout:
            logger.debug('socket timeout in stdout')
        else:
            return output

    def ssh_send_command_2(self, command, n=3):
        """ tbc """
        logger.debug("fun_call: " + sys._getframe().f_code.co_name)
        logger.debug(command)
        try:
            if self.is_connected():
                self.stdin, self.stdout, self.stderr = self.ssh_client.exec_command(command)
            else:
                self.ssh_client.connect(hostname=self.host, username=self.ssh_user, password=self.ssh_password)
                self.stdin, self.stdout, self.stderr = self.ssh_client.exec_command(command)
        except socket.error:
            if n > 0:
                logger.exception("socket.error in SshSendCommand2")
                self.ssh_send_command_2(command, n=n - 1)
            else:
                raise

    def ssh_send_command_3(self, command):
        """ tbc """
        logger.debug("fun_call: " + sys._getframe().f_code.co_name)
        logger.debug(command)
        if self.is_connected():
            self.stdin, self.stdout, self.stderr = self.ssh_client.exec_command(command)
        else:
            self.ssh_client.connect(hostname=self.host, username=self.ssh_user, password=self.ssh_password)
            self.stdin, self.stdout, self.stderr = self.ssh_client.exec_command(command)
        logger.debug(self.stdout.read())
        logger.debug(self.stderr.read())

    def transfer_file_from_remote_ssh_host(self, cwd, remote_filename, local_filename, n=3):
        """ tbc """
        try:
            sftp = self.ssh_client.open_sftp()
            sftp.chdir(cwd)
            sftp.get(remote_filename, local_filename)
            sftp.close()
        except paramiko.SSHException as e:
            logger.exception("retrying sftp transfer")
            try:
                if self.is_connected():
                    if n > 0:
                        self.transfer_file_from_remote_ssh_host(cwd, remote_filename, local_filename, n=n - 1)
                    else:
                        raise e
            except AttributeError:
                raise e

    def transfer_file_to_remote_ssh_host(self, cwd, remote_filename, local_filename):
        """ tbc """
        with self.ssh_client.open_sftp() as sftp:
            try:
                sftp.chdir(cwd)
                sftp.put(remote_filename, local_filename)
                sftp.close()
                logger.debug(remote_filename, ' has been put on remote machine in ', cwd)
                return True
            except IOError:
                sftp.mkdir(cwd)
                sftp.chdir(cwd)
                sftp.put(remote_filename, local_filename)
                sftp.close()
                logger.debug(remote_filename, ' has been put on remote machine in ', cwd)
                return True

    def sftp_get_last_modification_time(self, path):
        """ tbc """
        logger.debug("fun_call: " + sys._getframe().f_code.co_name)
        with self.ssh_client.open_sftp() as sftp:
            logger.debug(path)
            try:
                sftp.chdir(path)
                mtime = sftp.stat(path)
                return mtime.st_mtime
            except IOError:
                logger.debug("no path on sftp server")
                return None

    def transfer_folder_to_remote_ssh_host(self, remote_dir, local_dir):
        """ tbc """
        logger.debug("fun_call: " + sys._getframe().f_code.co_name)
        with self.ssh_client.open_sftp() as sftp:
            try:
                sftp.chdir(remote_dir)
                logger.debug('Remote dir = {}'.format(remote_dir))
            except IOError:
                sftp.mkdir(remote_dir)
                sftp.chdir(remote_dir)
            for root, dirs, files in os.walk(local_dir, topdown=True):
                dirs[:] = [d for d in dirs if not d.startswith('.')]
                for name in files:
                    logger.debug(name)
                    logger.debug(root)
                    print(os.path.join(root, name))

                    sftp.put(os.path.join(root, name), name)
                    logger.debug(os.path.join(root, name))

    def get_file_from_remote_ssh_host(self, filename=r"/flash/FileDirectory.xml"):
        """ tbc """
        sftp = self.ssh_client.open_sftp()
        fileObj = sftp.file(filename)
        text = fileObj.read()
        fileObj.close
        sftp.close
        return text

    def ssh_send_cmd_asynchronic(self, command, timeout2=10):
        """ tbc """
        self.stdin, self.stdout, self.stderr = self.ssh_client.exec_command(command)
        self.AprThread = self.AsynchronicPipeRead(self.stdout, self.outputSshCommandList)
        self.AprThread.start()

    def ssh_build_channel(self):
        self.channel = self.ssh_client.get_transport().open_session()
        self.channel.get_pty()
        self.channel.invoke_shell()

    def ssh_close_channel(self):
        self.channel.close()

    def ssh_write_cmd_on_channel(self, cmd, waittime=1):
        self.channel.send(cmd + "\n")
        sleep(waittime)

    def ssh_read_from_channel(self, ammount):
        self.last_output = self.channel.recv(ammount)
        return self.last_output

    def ssh_kill_cmd_asynchronic(self):
        """ tbc """
        self.stdin.write("0x32\n")
        self.stdin.flush()

    def ssh_close_connection(self):
        """ tbc """
        try:
            self.ssh_client.close()
        except AttributeError as e:
            print(" ex. in SshCloseConnection" + str(e))

    def ssh_kill_process(self, pattern):
        """ tbc """
        path = r"pgrep -f '{}' | xargs kill".format(pattern)
        self.ssh_send_command_2(path)

    def ssh_kill_process_forced(self, pattern):
        """ tbc """
        path = r"pgrep -f '{}' | xargs kill -9".format(pattern)
        self.ssh_send_command_2(path)

    def ssh_kill_windows_process(self, pattern):
        """ tbc """
        path = r"taskkill /F /IM {}".format(pattern)
        self.ssh_send_command_2(path)

    def ssh_kill_windows_processes(self, pattern):
        """
        kill multiple processes by image name
        :param pattern: list of processes (ie. ['calc.exe', 'notepad.exe']
        :return:
        """
        path = r"taskkill /F"
        for process in pattern:
            path += " /IM {}".format(process)
        self.ssh_send_command_2(path)

    def ssh_kill_windows_process_by_pid(self, pid):
        """ tbc """
        path = r"taskkill /F /PID {}".format(pid)
        self.ssh_send_command_2(path)

    def ssh_kill_windows_process_by_wmic(self, pattern):
        """ tbc """
        path = r'wmic PROCESS Where "CommandLine Like "%{}%"" get Processid'.format(pattern)
        output = self.ssh_send_cmd_and_return_output(path)
        for j in output:
            if j and j != 'ProcessId':
                self.ssh_kill_windows_process_by_pid(j)
        self.ssh_send_command_2(path)

    def invokeshell(self):
        """ tbc """
        self.shell = self.ssh_client.invoke_shell()
        self.read_from_shell('$ ')

    def ssh_get_ipy_path(self):
        r""" Returns the full IronPython path, x86 or x32
        :return path (ie. "C:\Program Files\IronPython 2.7\ipy32.exe")
        """

        program_files_86 = r'C:\Program Files (x86)\IronPython 2.7\ipy.exe'
        program_files_32 = r'C:\Program Files\IronPython 2.7\ipy32.exe'

        cmd_exec = r"[ -e '"'{}'"' ]; echo $?".format(program_files_86)
        rc = self.ssh_send_cmd_and_return_output(cmd_exec)
        if '0' in str(rc):
            return r'"{}"'.format(program_files_86)
        else:
            return r'"{}"'.format(program_files_32)


if __name__ == '__main__':
    sshParamikoObj = SshClient("127.0.0.1", "ute", "ute", connect=False)
